/* CM2 base address */
pub const OMAP4430_CM2_BASE: u32 = 0x4a008000;

/* Dependency: OMAP2_L4_IO_ADDRESS is supplied by the surrounding bindings. */
macro_rules! OMAP44XX_CM2_REGADDR {
    ($inst:expr, $reg:expr) => {
        OMAP2_L4_IO_ADDRESS(OMAP4430_CM2_BASE + ($inst) + ($reg))
    };
}
pub(crate) use OMAP44XX_CM2_REGADDR;

